cd /workspace/project/wasd-clone && cat > /tmp/persistence_fix.patch << 'ENDPATCH'
--- a/server/src/core/WorldTick.ts
+++ b/server/src/core/WorldTick.ts
@@ -447,6 +447,19 @@ export class WorldTick {
   }
   async init() {
-    if (!this.persistence) return;
+    // Ensure persistence is initialized properly
+    if (!this.persistence) {
+      console.warn("[WorldTick.init] Persistence not available, using in-memory fallback");
+      return;
+    }
+    try {
     await this.persistence.init();
-    const connected = await this.persistence.testConnection();
-    if (connected) {
-      console.log("✅ Persistence backend connection verified.");
+      const connected = await this.persistence.testConnection();
+      if (connected) {
+        console.log("✅ Persistence backend connection verified.");
+      }
+    } catch (persistError) {
+      console.warn("[WorldTick.init] Persistence init failed:", persistError);
     }
     this.areMode = this.runtimeSettings.getAREMode();
ENDPATCH


echo "Patch erstellt"
